using System;
using System.Collections.Generic;
using System.Linq;
using Metafarm.Twin.Core.Api;
using Metafarm.Twin.Core.Yield;
using Newtonsoft.Json;
using Xunit;

namespace Metafarm.Twin.Core.Tests
{
    /// <summary>
    /// Payload verification on a large tree. Samples/claim-payloads.large-tree.sample.json holds 64 seeded holders
    /// of a 4,096-holder simulation cycle (about 3,000 leaves, proofs up to 12 deep), generated by
    /// large-holder.test-support.ts and drift-checked by large-holder-envelope.test.ts. The client must verify every
    /// claim exactly as the platform does, compute the same RFC 9162 path lengths, refuse any altered path entry,
    /// and agree that holders allocated 0 (zero_amount) have no claim.
    /// </summary>
    public class LargeTreeCrossStackTests
    {
        public sealed class Lookup
        {
            [JsonProperty("partyId")] public string PartyId;
            [JsonProperty("status")] public string Status;
            [JsonProperty("reason")] public string Reason;
            [JsonProperty("deferredReason")] public string DeferredReason;
        }

        public sealed class Sample
        {
            [JsonProperty("payableCount")] public long PayableCount;
            [JsonProperty("publishedTree")] public PublishedClaimTree PublishedTree;
            [JsonProperty("lookups")] public List<Lookup> Lookups;
            [JsonProperty("claims")] public List<ClaimPayload> Claims;
        }

        private static Sample Load() => TwinJson.Deserialize<Sample>(Samples.Read("claim-payloads.large-tree.sample.json"));

        private static ClaimPayload Copy(ClaimPayload c) => JsonConvert.DeserializeObject<ClaimPayload>(JsonConvert.SerializeObject(c), TwinJson.Settings);

        private static byte[] Bytes(string hex)
        {
            var b = new byte[hex.Length / 2];
            for (var i = 0; i < b.Length; i++) b[i] = Convert.ToByte(hex.Substring(2 * i, 2), 16);
            return b;
        }

        private static string Hex(byte[] b) => string.Concat(b.Select(x => x.ToString("x2")));

        /// <summary>RFC 9162 audit path length of leaf i in a tree of n leaves, from the definition.</summary>
        private static int PathLength(long i, long n)
        {
            if (n <= 1) return 0;
            long k = 1;
            while (k * 2 < n) k *= 2;
            return 1 + (i < k ? PathLength(i, k) : PathLength(i - k, n - k));
        }

        [Fact]
        public void EveryClaimOnTheLargeTreeVerifies()
        {
            var s = Load();
            Assert.True(s.PublishedTree.Simulation);
            Assert.Equal(s.PayableCount, s.PublishedTree.TreeSize);
            Assert.True(s.PublishedTree.TreeSize > 2048, "the tree must be large");
            Assert.True(s.Claims.Count > 32, "the sample must hold many claims");
            foreach (var c in s.Claims)
            {
                Assert.NotEqual("0", c.Amount);
                Assert.Equal(PathLength(c.LeafIndex, c.TreeSize), c.Path.Count);
                Assert.True(c.Path.Count <= 12);
                Assert.True(ClaimPayloadVerification.Verify(c, s.PublishedTree));
            }
        }

        [Fact]
        public void LookupsAgreeWithTheClaimsAndTheZeroAmountSafeguard()
        {
            var s = Load();
            var claimed = new HashSet<string>(s.Claims.Select(c => c.PartyId));
            Assert.Equal(64, s.Lookups.Count);
            foreach (var l in s.Lookups)
            {
                if (l.Status == "claim") Assert.Contains(l.PartyId, claimed);
                else Assert.DoesNotContain(l.PartyId, claimed);
            }
            var zeros = s.Lookups.Where(l => l.Status == "no_leaf" && l.Reason == "deferred" && l.DeferredReason == "zero_amount").ToList();
            Assert.True(zeros.Count > 0, "the sample must contain holders allocated 0");
            Assert.Equal(s.Lookups.Count(l => l.Status == "claim"), s.Claims.Count);
        }

        [Fact]
        public void AnyAlteredPathEntryOrIndexIsRefused()
        {
            var s = Load();
            foreach (var c in s.Claims.Take(8))
            {
                for (var i = 0; i < c.Path.Count; i++)
                {
                    var altered = Copy(c);
                    altered.Path[i] = (altered.Path[i][0] == '0' ? "1" : "0") + altered.Path[i].Substring(1);
                    Assert.False(ClaimPayloadVerification.Verify(altered, s.PublishedTree));
                }
                var moved = Copy(c);
                moved.LeafIndex = c.LeafIndex == 0 ? 1 : c.LeafIndex - 1;
                Assert.False(ClaimPayloadVerification.Verify(moved, s.PublishedTree));
            }
        }

        [Fact]
        public void AZeroAmountLeafIsRefusedOnTheLargeTree()
        {
            var s = Load();
            var c = s.Claims[s.Claims.Count - 1];
            var zero = Bytes(c.LeafBytes);
            for (var i = 185; i < 193; i++) zero[i] = 0;
            Assert.Throws<ArgumentException>(() => ClaimLeafCodec.Decode(zero));
            var forged = Copy(c);
            forged.Amount = "0";
            forged.LeafBytes = Hex(zero);
            Assert.False(ClaimPayloadVerification.Verify(forged, s.PublishedTree));
        }
    }
}
